"use strict";(globalThis.webpackChunkshellui_docs=globalThis.webpackChunkshellui_docs||[]).push([[490],{9625(e){e.exports=JSON.parse('{"version":{"pluginId":"email","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/email/","label":"email-service documentation","docId":"index","unlisted":false},{"type":"link","href":"/email/integration","label":"Integration contract","docId":"integration","unlisted":false},{"type":"link","href":"/email/authentication","label":"Authentication","docId":"authentication","unlisted":false},{"type":"link","href":"/email/providers","label":"Providers","docId":"providers","unlisted":false},{"type":"link","href":"/email/templates","label":"Templates","docId":"templates","unlisted":false},{"type":"link","href":"/email/library","label":"Template library","docId":"library","unlisted":false},{"type":"link","href":"/email/rules","label":"Email rules","docId":"rules","unlisted":false},{"type":"link","href":"/email/lanes","label":"Lanes","docId":"lanes","unlisted":false},{"type":"link","href":"/email/events","label":"Suggested events","docId":"events","unlisted":false},{"type":"link","href":"/email/metrics","label":"Metrics","docId":"metrics","unlisted":false},{"type":"link","href":"/email/actions","label":"Shellui Actions (outbound webhooks)","docId":"actions","unlisted":false},{"type":"link","href":"/email/n8n","label":"Using Shellui webhooks with n8n","docId":"n8n","unlisted":false},{"type":"link","href":"/email/configuration","label":"Configuration","docId":"configuration","unlisted":false},{"type":"link","href":"/email/security","label":"Production security","docId":"security","unlisted":false}]},"docs":{"actions":{"id":"actions","title":"Shellui Actions (outbound webhooks)","description":"Company owners and staff can subscribe to email-service domain events. Delivery uses the same outbox, signing, and retry rules as storage-service and hosting-service. There is no separate bus.","sidebar":"tutorialSidebar"},"authentication":{"id":"authentication","title":"Authentication","description":"Two credentials share Authorization: Bearer.","sidebar":"tutorialSidebar"},"broadcasts":{"id":"broadcasts","title":"Broadcasts","description":"A broadcast is one email a company writes once and sends to many of its users: product news, a launch, a policy change. Company owners and staff create them in the admin under Email > Broadcasts."},"configuration":{"id":"configuration","title":"Configuration","description":"Copy .env.example to .env. Production (DEBUG=false) refuses to boot without:","sidebar":"tutorialSidebar"},"events":{"id":"events","title":"Suggested events","description":"GET /api/v1/catalog is the live list. This page records the v1 catalog so the admin app can show which events exist and which ones used to be on by default.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"email-service documentation","description":"email-service sends Shellui mail. The HTTP API lives at https://email.shellui.com. This docs site is published separately so the API host stays an API.","sidebar":"tutorialSidebar"},"integration":{"id":"integration","title":"Integration contract","description":"This page is the contract for identity-service, storage-service, hosting-service, and the Shellui admin app. Implement against these paths, fields, and error codes. Do not infer a second shape from another service.","sidebar":"tutorialSidebar"},"lanes":{"id":"lanes","title":"Lanes","description":"Three lanes. A template\'s lane_class is fixed. /send cannot move a transactional template onto auth.","sidebar":"tutorialSidebar"},"library":{"id":"library","title":"Template library","description":"The library is the set of designs an event email starts from. It holds 40 built-in designs and the company\'s own templates.","sidebar":"tutorialSidebar"},"metrics":{"id":"metrics","title":"Metrics","description":"Admin stats","sidebar":"tutorialSidebar"},"n8n":{"id":"n8n","title":"Using Shellui webhooks with n8n","description":"email-service can POST signed JSON to an n8n Webhook node when a message changes state. The signing and retry rules match identity-service, storage-service, and hosting-service, so one n8n pattern works for every Shellui webhook.","sidebar":"tutorialSidebar"},"newsletters":{"id":"newsletters","title":"Newsletters","description":"A newsletter is a mailing list anyone can join from a company\'s website, with or without an account. People sign up with their email address, get a confirmation email, and are on the list once they click it (double opt-in). The company then writes issues as broadcasts and sends them to the list. Company owners and staff manage lists in the admin under Email > Newsletters."},"providers":{"id":"providers","title":"Providers","description":"Sending goes through apps.providers. Workers call EmailProvider.send and do not import a vendor SDK.","sidebar":"tutorialSidebar"},"rules":{"id":"rules","title":"Email rules","description":"A company email rule is one send instruction, the same idea as a Shellui Actions webhook rule. The admin \\"Email and webhooks\\" page lists email rules next to webhook rules, ordered by event.","sidebar":"tutorialSidebar"},"security":{"id":"security","title":"Production security","description":"Controls for running email-service next to identity-service 0.5.0 or newer.","sidebar":"tutorialSidebar"},"templates":{"id":"templates","title":"Templates","description":"An event email is a company template: a copy of a library design made for one event. It is created with an email rule, edited in the admin, and deleted with its rule. Copies are not listed in the library, and a copy never changes when the library template it came from changes.","sidebar":"tutorialSidebar"}}}}')}}]);